contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // park `amount` wei on c via its payable fallback
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);
        uint256 parked = address(c).balance;
        require(parked >= amount);
        // deciding call: succeeds or reverts, both fine
        (bool ok, ) = address(c).call("");
        // rule: if go() succeeded, c must hold zero Ether; if it reverted, balance is untouched
        assert((ok && address(c).balance == 0) || (!ok && address(c).balance == parked));
    }
    receive() external payable {}
    fallback() external payable {}
}

